#include "test_registry.hpp"
#include "local_order_book.hpp"
md::MarketDataMessage make(md::MessageType t,std::uint64_t id,md::Side side,std::int64_t px,std::uint32_t qty){md::MarketDataMessage m{};m.protocol_version=1;m.type=t;m.sequence_number=1;m.source_timestamp_ns=1;m.instrument_id=7;m.order_id=id;m.side=side;m.price_ticks=px;m.quantity=qty;return m;}
TEST(book_add_execute_cancel_replace){md::LocalOrderBook b;REQUIRE(b.apply(make(md::MessageType::ADD_ORDER,1,md::Side::BUY,100,100)));REQUIRE(b.apply(make(md::MessageType::ADD_ORDER,2,md::Side::SELL,105,50)));auto t=b.top(7);REQUIRE(t.bid && t.ask);REQUIRE_EQ(t.bid->quantity,100U);REQUIRE_EQ(t.ask->quantity,50U);REQUIRE(b.apply(make(md::MessageType::REPLACE_ORDER,1,md::Side::BUY,102,120)));t=b.top(7);REQUIRE_EQ(t.bid->price_ticks,102);REQUIRE(b.apply(make(md::MessageType::EXECUTE_ORDER,1,md::Side::BUY,102,20)));t=b.top(7);REQUIRE_EQ(t.bid->quantity,100U);REQUIRE(b.apply(make(md::MessageType::CANCEL_ORDER,2,md::Side::SELL,105,50)));t=b.top(7);REQUIRE(!t.ask.has_value());}
TEST(book_multiple_instruments){md::LocalOrderBook b;auto a=make(md::MessageType::ADD_ORDER,10,md::Side::BUY,100,1);a.instrument_id=1;auto c=make(md::MessageType::ADD_ORDER,20,md::Side::BUY,200,2);c.instrument_id=2;REQUIRE(b.apply(a));REQUIRE(b.apply(c));REQUIRE_EQ(b.top(1).bid->price_ticks,100);REQUIRE_EQ(b.top(2).bid->price_ticks,200);}
